query Diablo4TakeoverQuery {
  game: diablo4 {
    settings {
      banners {
        takeovers {
          ...NgfTakeoverFragment
        }
      }
    }
  }
}

fragment NgfTakeoverFragment on NgfTakeoverBanner {
  enabled
  display {
    ...NgfBannerDisplayFragment
  }
  content {
    __typename
    navigationUrl
    imageAlt
    images {
      screenWidth
      imageUrl
      fallbackImageUrl
    }
  }
}

fragment NgfBannerDisplayFragment on NgfBannerDisplay {
  slug
  abTestKey
  allowedUserLevels
  platform
  whiteListUserIds
  countries
  minScreenWidth
  countries
  urlMatchPatterns
  distribution
  urlExcludePatterns
}
